import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Report: Language cleanup, transform engine, and engine-parity push","description":"","frontmatter":{"title":"Report: Language cleanup, transform engine, and engine-parity push","type":"report","date":"2026-02"},"headers":[],"relativePath":"handl/project/reports/2026-02-language-cleanup.md","filePath":"vendored/handl/project/reports/2026-02-language-cleanup.md"}`),a={name:`handl/project/reports/2026-02-language-cleanup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t('<h1 id="report-language-cleanup-transform-engine-and-engine-parity-push" tabindex="-1">Report: Language cleanup, transform engine, and engine-parity push <a class="header-anchor" href="#report-language-cleanup-transform-engine-and-engine-parity-push" aria-label="Permalink to “Report: Language cleanup, transform engine, and engine-parity push”">​</a></h1><p>Date: 2026-02 (this session). Merge heads: <code>c0ba7dbf</code>, <code>efa6cf7e</code>, <code>77c61969</code>.</p><p>This report covers three merged rounds of work: the ADR-0094 transform-engine roadmap completion, language cleanup (<code>let</code> removal, genericity audit), and the final arc (broken-main repair, dialect routing, import unification, compiled-engine parity, AST caching).</p><h2 id="_1-transform-engine-roadmap-adr-0094-—-complete" tabindex="-1">1. Transform engine roadmap (ADR-0094) — complete <a class="header-anchor" href="#_1-transform-engine-roadmap-adr-0094-—-complete" aria-label="Permalink to “1. Transform engine roadmap (ADR-0094) — complete”">​</a></h2><ul><li><strong><code>AstNode.span</code> populated</strong> across all Pratt productions (<code>e26d7bbc</code>): every node carries byte offsets — atoms, infix, delimited containers, statements.</li><li><strong>AST-derived lint fixes</strong> (<code>8fa2d273</code>): <code>simplify-paren</code> computes fix ranges from node spans (token-walk helpers deleted); LSP quickfix and <code>hnl transform --plan</code> ride real spans.</li><li><strong>Lower-pass audit</strong> (<code>9ed85387</code>): honest result — the object-key heuristic was the only real lowering candidate (already covered by <code>transform.lower.entry</code>); documented retained fallbacks + cranelift non-opt-in (dep cycle); added a bypass test.</li><li><strong>Check-path validation</strong> (<code>9e677d2c</code>): the typechecker bootstrap now embeds <code>transforms.yaml</code>, lowers <code>desugar:</code>, and runs <code>validate_transforms</code>; errors surface as <code>language error: ...</code>. <code>hnl check</code> added as a <code>typecheck</code> alias.</li><li><strong>Parallel engine verdict</strong> (<code>7542f64d</code>): sweep 500→50k stmts showed no crossover — merge overhead dominates. Default threshold raised to 1M nodes; shared-arena noted as the future lever.</li><li><strong>Formatter-preserving emitter</strong> (<code>109c79f1</code> + <code>9c78787a</code>): <code>plugin-engine-fmt::PreserveEmitter</code> — trace-driven splice: unchanged subtrees copy <code>src[span]</code> verbatim, changed subtrees re-render via the data-driven <code>FormatEngine</code>. Powers <code>hnl transform --emit source</code> / <code>--write</code>; refuses on lowering passes that produce internal-form nodes.</li><li><strong>LSP rewrite action</strong> (<code>43465f35</code>): <code>apply_rule</code> → <code>PreserveEmitter</code> → <code>WorkspaceEdit</code> bridge; &quot;Apply rewrite&quot; quickfix for simplify-paren.</li><li><strong>ADR-0093 retro-doc</strong> (<code>3bf183d3</code>): the str/char/unicode layering ADR was missing; written retroactively incl. the four runtime-fix rationales.</li></ul><h2 id="_2-language-cleanup" tabindex="-1">2. Language cleanup <a class="header-anchor" href="#_2-language-cleanup" aria-label="Permalink to “2. Language cleanup”">​</a></h2><ul><li><strong><code>let</code> removed entirely</strong> (<code>ea8fcd4e</code>): grammar/ast/eval/types rows deleted; <code>token.keyword.let</code>/<code>lex.keyword.let</code> kept as a tombstone so <code>let x :: v</code> fails with <code>unexpected token</code> rather than silently lexing as an identifier. <code>stmt.let</code> had no producer — deleted. Corpus cases rewritten to <code>do { x = y; ... }</code> binds. ADR-0079 amended.</li><li><strong>Pratt <code>match</code>/<code>data</code>/<code>from</code> branches closed</strong> (<code>b12df6d8</code>, <code>4f700d54</code>): three new generic <code>AstShapeRef</code> fields — <code>child_binding_powers</code>, <code>keyword_clauses</code> (optional <code>open &lt;expr&gt; close</code> after a fixed child), <code>payload_extract</code> — plus <code>trailing_tokens</code> (<code>TokenStep</code> = one-of kinds + optional + payload capture) covering <code>import * as alias</code>. ~150 lines of special-casing deleted; the Pratt dispatch is now fully data-driven.</li><li><strong>Token categories</strong> (<code>845d0704</code>): <code>TokenKindDef</code> gained optional <code>category</code>/<code>pair</code>/<code>doc</code> fields; all <code>token.*</code> literals eliminated from host-lsp, host-tooling, plugin-ext-fmt, plugin-ext-lint.</li><li><strong>Final genericity audit</strong> (<code>bed3ef8e</code>): &quot;~70 hits&quot; was stale — real residual is ~29, all documented bootstrap/identity-specific. <code>arrow_parser</code> ruled intentional bootstrap (combinator vocabulary).</li><li><strong>ADR-0092 pure-handl test framework</strong> (<code>27e299c3</code>, cherry-picked from <code>chore/kit-data-config-fold</code>): all 12 Rust handls → <code>handl-packages/test/*.hnl</code> (<code>assert</code>, <code>property</code>, <code>benchmark</code>, <code>fuzz</code>, <code>snapshot</code>, <code>test</code>); <code>plugin-engine-test::framework</code> reduced to the assert-failure side-channel.</li><li><strong>Declarative desugar</strong> (<code>6af2e51f</code> + <code>7760f9df</code>, reconciled in <code>d6708bdc</code>): 5 of 8 desugar natives migrated to <code>transforms.yaml</code> (<code>while</code>, <code>do-while</code>, <code>for</code>, <code>nullish</code>, <code>opt-chain</code>) — the assumed blockers (fresh-name generation, recursion) turned out unneeded for fixed <code>__</code>-binders; <code>RewriteStep::Fresh</code> landed for hygiene anyway. Only <code>desugar.data</code>/<code>desugar.match_recursor</code> stay native (constructor iteration + env lookup — macro-system territory).</li><li><strong>ADR-0089 tail</strong> (<code>1dbcbe67</code>): suite events already emitted per-module; reporters now render <code>== module ==</code> headers, <code>suites</code> JSON array, and <code>expected</code>/<code>actual</code>/<code>diff</code> failure detail.</li></ul><h2 id="_3-final-arc-—-repair-parity" tabindex="-1">3. Final arc — repair + parity <a class="header-anchor" href="#_3-final-arc-—-repair-parity" aria-label="Permalink to “3. Final arc — repair + parity”">​</a></h2><ul><li><strong>Broken main repaired</strong> (<code>d6708bdc</code>): <code>transforms.yaml</code> had two concatenated rule generations → every <code>hnl</code> command failed at Language assembly. The tangle also exposed <strong>three pre-existing eval bugs</strong>: <ul><li>block <code>x = y</code> never updated enclosing scopes (define-only);</li><li><code>rec</code> fixpoint couldn&#39;t detect nested writes;</li><li><code>__fresh_*</code> names collided with the <code>_</code> wildcard convention. All fixed in tree-walk + bytecode. <strong>Semantic change: block assigns are now update-or-define</strong> — <code>if c { x = 5 }</code> mutates an outer <code>x</code> (required for the desugar to be meaningful; documented in AGENTS.md).</li></ul></li><li><strong>Dialect routing</strong> (<code>f3e9e73b</code>): the &quot;32 unparseable files&quot; were mostly <em>dialect</em> files — <code>hnl typecheck</code> now routes contract files (<code>axiom</code>/<code>requires:</code>/<code>guarantee:</code>) to <code>parse_contracts</code> and arrow-module files (<code>cap</code>/<code>op</code>/<code>handl</code>/<code>tag</code>, <code>arr</code>/<code>&gt;&gt;&gt;</code>/<code>|||</code> graphs) to <code>parse_arrow_module</code>. <code>axiom</code> got a canonical alias row. Legacy <code>-&gt;</code>/ <code>|&gt;</code>/<code>rec {}</code>/leading-<code>&gt;&gt;&gt;</code> sources rewritten. <strong>Parse failures: 30 → 0; typecheck failures: 128 → 57</strong> (remaining are genuine unbound-wire env gaps).</li><li><strong>Import unification</strong> (<code>ecb81343</code>, ADR-0096 amendment): <code>import &quot;&amp;lt;spec&gt;&quot;</code>, <code>from &quot;&amp;lt;spec&gt;&quot; import &amp;lt;name&gt; [as x]</code>, `from &quot;&lt;spec&gt;&quot; import <ul><li>[as x]<code>all resolve through</code>prim_import<code>in all three engines with named-projection errors; module-name (host-chain) declarations documented as decorative under</code>hnl run<code>/</code>test<code>; arrow-loader </code>import x from &quot;p&quot;` documented as dialect-fixed.</li></ul></li><li><strong><code>Bind</code> on compiled engines</strong> (<code>15595901</code>): <code>eval_rec</code> + update-or-define <code>ScopeStack::assign</code> in bytecode and cranelift — <strong>all 44 handl-defining-handl corpus cases now run on all three engines</strong>; new <code>bind_rec_parity.rs</code> exercises real <code>do {}</code>/<code>while</code>/ <code>do-while</code>/<code>for</code> source through <code>Runtime::run</code> per engine.</li><li><strong>AST cache</strong> (<code>c12c498d</code>): <code>HandlFunction::call</code> caches parsed applied-form ASTs per <code>(module_id, func, arity)</code>; tree-walk gained <code>eval_shared(&amp;Rc&lt;Ast&gt;)</code> eliminating per-call arena clones. <strong>~19× warm-call speedup, ~7× on loader workloads.</strong> <code>loader.hnl</code> remains <strong>opt-in</strong>: interpreted <code>str.*</code>/<code>char.*</code> eval is still ~43 s on a 22k-char module (module-record caching was tried and reverted — env serialization OOMs).</li><li><strong>Docs</strong> (<code>454c5fbe</code>, <code>3f944937</code>): README crate map + <code>hnl</code> subcommands rewritten; ADR-0095 collision resolved (module-resolution → 0096); dogfood gate documented (CI workflow exists, informational until clean).</li></ul><h2 id="remaining-open-items-by-design-or-blocked" tabindex="-1">Remaining open items (by design or blocked) <a class="header-anchor" href="#remaining-open-items-by-design-or-blocked" aria-label="Permalink to “Remaining open items (by design or blocked)”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Status</th></tr></thead><tbody><tr><td><code>desugar.data</code> / <code>desugar.match_recursor</code> natives</td><td>Permanent native floor unless transform vocabulary grows env lookup + constructor iteration</td></tr><tr><td><code>f(...xs)</code> call-site spread</td><td>Needs an eval-splice op; no live usage yet</td></tr><tr><td><code>loader.hnl</code> as default</td><td>Blocked on interpreted-eval cost; AST cache landed but insufficient alone</td></tr><tr><td>Typecheck env gaps (~57 files, <code>[unbound-wire]</code>)</td><td>Match-arm binder scoping, module envs — real remaining checker work</td></tr><tr><td>Dialect routing for <code>lint</code>/<code>fmt</code>/<code>run</code>/<code>test</code></td><td>Only <code>typecheck</code> routes dialects (dep-cycle constraint)</td></tr><tr><td>RFC-0001–0007 self-hosting, arrow macros, registry module resolution</td><td>Backlog by design</td></tr><tr><td><code>{ x :: v }</code> multi-statement brace bodies</td><td>Canonical form is <code>do { ... }</code>; object-literal ambiguity documented</td></tr></tbody></table>',11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};